mapper.select:
SELECT , d.DEPT_NM, c.CD_NM AS POS_NM FROM HR_EMP e LEFT JOIN HR_DEPT d ON d.DEPT_CD = e.DEPT_CD LEFT JOIN CM_CODE c ON c.GRP_CD = 'POS' AND c.CD = e.POS_CD
AND e.RETIRE_YN = 'N'
AND e.EMP_NO IN #{no}
ORDER BY ${orderBy} LIMIT #{offset}, #{limit}

mapper.update:
UPDATE HR_EMP
EMP_NM = #{empNm}, EMAIL = #{email}, DEPT_CD = #{deptCd},
WHERE EMP_NO = #{empNo}

mapper.select:
SELECT e.EMP_NO, e.EMP_NM
  FROM HR_EMP e
 WHERE 1 = 1

    AND e.DEPT_CD = #{keyword}
    AND e.POS_CD = #{keyword}
    AND e.EMP_NM = #{keyword}
